class MyCircularQueue:
    def __init__(self, k):
        self.capacity = k
        self.data = []                                                     # a plain list, growing/shrinking like a normal queue

    def en_queue(self, value):
        if len(self.data) >= self.capacity:
            return False
        self.data.append(value)
        return True

    def de_queue(self):
        if not self.data:
            return False
        self.data.pop(0)                                                   # O(n) shift to remove from the front
        return True

    def front(self):
        return self.data[0] if self.data else -1

    def rear(self):
        return self.data[-1] if self.data else -1

    def is_empty(self):
        return len(self.data) == 0

    def is_full(self):
        return len(self.data) == self.capacity


if __name__ == "__main__":
    q = MyCircularQueue(3)
    print(q.en_queue(1))
    print(q.en_queue(2))
    print(q.en_queue(3))
    print(q.en_queue(4))
    print(q.rear())

