import java.util.*;

public class Main {
    class MyCircularQueue {
        int capacity;
        List<Integer> data = new ArrayList<>();                                     // a plain list, growing/shrinking like a normal queue

        MyCircularQueue(int k) { capacity = k; }

        boolean enQueue(int value) {
            if (data.size() >= capacity) return false;
            data.add(value);
            return true;
        }

        boolean deQueue() {
            if (data.isEmpty()) return false;
            data.remove(0);                                                              // O(n) shift to remove from the front
            return true;
        }

        int Front() { return data.isEmpty() ? -1 : data.get(0); }
        int Rear() { return data.isEmpty() ? -1 : data.get(data.size() - 1); }
        boolean isEmpty() { return data.isEmpty(); }
        boolean isFull() { return data.size() == capacity; }
    }

    public static void main(String[] args) {
        MyCircularQueue q = new MyCircularQueue(3);
        System.out.println(q.enQueue(1));
        System.out.println(q.enQueue(2));
        System.out.println(q.enQueue(3));
        System.out.println(q.enQueue(4));
        System.out.println(q.Rear());
    }
}

