class MyCircularQueue:
    def __init__(self, k):
        self.capacity = k
        self.data = [0] * k                                                 # a FIXED-SIZE array, reused circularly, never resized
        self.head = 0                                                       # index of the current front element
        self.count = 0                                                      # how many slots are currently occupied

    def en_queue(self, value):
        if self.is_full():
            return False
        tail = (self.head + self.count) % self.capacity                   # the next free slot, wrapping around via modulo
        self.data[tail] = value
        self.count += 1
        return True

    def de_queue(self):
        if self.is_empty():
            return False
        self.head = (self.head + 1) % self.capacity                       # advance the front pointer, wrapping around
        self.count -= 1
        return True

    def front(self):
        return -1 if self.is_empty() else self.data[self.head]

    def rear(self):
        return -1 if self.is_empty() else self.data[(self.head + self.count - 1) % self.capacity]

    def is_empty(self):
        return self.count == 0

    def is_full(self):
        return self.count == self.capacity


if __name__ == "__main__":
    q = MyCircularQueue(3)
    print(q.en_queue(1))
    print(q.en_queue(2))
    print(q.en_queue(3))
    print(q.en_queue(4))
    print(q.rear())

